const changeReportStatus = async (report, status) => {
  if (!REPORT_STATUSES.includes(status) || statusBusyId === report.id) return;
  const sequence = (statusChangeSequence.current.get(report.id) || 0) + 1;
  statusChangeSequence.current.set(report.id, sequence);
  const latest = reportsRef.current.find(row => row.id === report.id) || report;
  setStatusBusyId(report.id);
  setError("");
  try {
    const { data } = await base44.functions.invoke("fleetSystemReportAction", {
      action: "update_status",
      id: latest.id,
      status,
      expected_updated_date: latest.updated_date || "",
    });
    if (data?.error) throw new Error(data.error);
    if (statusChangeSequence.current.get(report.id) !== sequence) return;
    const updated = data?.report || latest;
    setReports(current => current.map(row => row.id === report.id ? updated : row));
  } catch (e) {
    if (statusChangeSequence.current.get(report.id) === sequence) {
      setError(e?.message || "Unable to update Fleet feedback status.");
    }
  } finally {
    if (statusChangeSequence.current.get(report.id) === sequence) setStatusBusyId("");
  }
};

